CREATE TABLE IF NOT EXISTS claude_code.codex_turns_v1 ON CLUSTER 'replicated'
(
  TurnHour DateTime CODEC(ZSTD(1)),
  UserIdentity String CODEC(ZSTD(1)),
  TurnId String CODEC(ZSTD(1)),
  Conversations AggregateFunction(groupUniqArray, String) CODEC(ZSTD(1)),
  StartTs SimpleAggregateFunction(min, DateTime64(9)) CODEC(ZSTD(1)),
  EndTs SimpleAggregateFunction(max, DateTime64(9)) CODEC(ZSTD(1)),
  SamplingSpans AggregateFunction(uniqExact, UInt64) CODEC(ZSTD(1)),
  LegacySpans AggregateFunction(uniqExact, UInt64) CODEC(ZSTD(1)),
  SamplingModels AggregateFunction(groupUniqArray, String) CODEC(ZSTD(1)),
  LegacyModels AggregateFunction(groupUniqArray, String) CODEC(ZSTD(1)),
  SamplingTries AggregateFunction(uniqExact, UInt64) CODEC(ZSTD(1)),
  Compactions AggregateFunction(uniqExact, UInt64) CODEC(ZSTD(1)),
  SpawnCalls AggregateFunction(uniqExact, UInt64) CODEC(ZSTD(1)),
  NamesTurnOnTools SimpleAggregateFunction(max, UInt8) CODEC(ZSTD(1)),
  AppVersion SimpleAggregateFunction(max, String) CODEC(ZSTD(1))
)
ENGINE = ReplicatedAggregatingMergeTree('/clickhouse/tables/{shard}/codex_turns_v1', '{replica}')
PARTITION BY toYYYYMM(TurnHour)
ORDER BY (UserIdentity, TurnHour, TurnId)
TTL TurnHour + INTERVAL 45 DAY TO VOLUME 'cold',
  TurnHour + INTERVAL 90 DAY DELETE
SETTINGS storage_policy = 'hot_cold';

CREATE MATERIALIZED VIEW IF NOT EXISTS claude_code.codex_turns_v1_mv ON CLUSTER 'replicated'
TO claude_code.codex_turns_v1
DEFINER = CURRENT_USER SQL SECURITY DEFINER AS
SELECT TurnHour, UserIdentity, TurnId,
  groupUniqArrayStateIf(turn_conversation, turn_conversation != '') AS Conversations,
  min(span_start) AS StartTs,
  max(span_end) AS EndTs,
  uniqExactStateIf(span_key, SpanName = 'codex.sampling') AS SamplingSpans,
  uniqExactStateIf(span_key, SpanName = 'run_sampling_request') AS LegacySpans,
  groupUniqArrayStateIf(span_model, SpanName = 'codex.sampling' AND span_model != '') AS SamplingModels,
  groupUniqArrayStateIf(span_model, SpanName = 'run_sampling_request' AND span_model != '') AS LegacyModels,
  uniqExactStateIf(span_key, SpanName = 'try_run_sampling_request') AS SamplingTries,
  uniqExactStateIf(span_key, SpanName = 'codex.compaction') AS Compactions,
  uniqExactStateIf(span_key, SpanName IN ('collaborationspawn_agent', 'collaborationfollowup_task', 'multi_agent_v1spawn_agent')) AS SpawnCalls,
  max(span_names_turn) AS NamesTurnOnTools,
  maxIf(span_version, span_version != '') AS AppVersion
FROM (
  SELECT toStartOfHour(toDateTime(intDiv(if(match(turn_id_raw, '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-7[0-9a-fA-F]{3}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')
        AND toInt64(reinterpretAsUInt64(reverse(unhex(concat(substring(turn_id_raw, 1, 8), substring(turn_id_raw, 10, 4)))))) >= toUnixTimestamp64Milli(Timestamp) - 604800000
        AND toInt64(reinterpretAsUInt64(reverse(unhex(concat(substring(turn_id_raw, 1, 8), substring(turn_id_raw, 10, 4)))))) <= toUnixTimestamp64Milli(Timestamp) + 86400000,
      toInt64(reinterpretAsUInt64(reverse(unhex(concat(substring(turn_id_raw, 1, 8), substring(turn_id_raw, 10, 4)))))), toUnixTimestamp64Milli(Timestamp)), 1000), 'UTC')) AS TurnHour,
    coalesce(nullIf(ResourceAttributes['user.email'], ''), nullIf(ResourceAttributes['enduser.id'], ''), '') AS UserIdentity,
    coalesce(nullIf(SpanAttributes['turn_id'], ''), SpanAttributes['turn.id']) AS turn_id_raw,
    turn_id_raw AS TurnId,
    SpanAttributes['conversation.id'] AS turn_conversation,
    Timestamp AS span_start,
    toDateTime64(fromUnixTimestamp64Milli(toUnixTimestamp64Milli(Timestamp) + intDiv(Duration, 1000000), 'UTC'), 9) AS span_end,
    SpanName,
    cityHash64(TraceId, SpanId) AS span_key,
    coalesce(nullIf(SpanAttributes['model'], ''), SpanAttributes['gen_ai.request.model']) AS span_model,
    ResourceAttributes['service.version'] AS span_version,
    toUInt8(length(extractGroups(span_version, '^(\\d+)\\.(\\d+)')) = 2
      AND (toFloat64OrZero(extractGroups(span_version, '^(\\d+)\\.(\\d+)')[1]) > 0 OR toFloat64OrZero(extractGroups(span_version, '^(\\d+)\\.(\\d+)')[2]) >= 166)) AS span_names_turn
  FROM claude_code.otel_traces
  WHERE ResourceAttributes['client'] = 'codex'
    AND (SpanAttributes['turn_id'] != '' OR SpanAttributes['turn.id'] != '')
    AND (1)
)
WHERE TurnId != ''
GROUP BY TurnHour, UserIdentity, TurnId;

